    # Initialize variables
    max_power = [0] * (M + 1)
    max_power[0] = 1
    dp = [[0] * (1 << S) for _ in range(M + 1)]
    dp[0][0] = 1

    # Fill the DP table
    for i in range(1, M + 1):
        for j in range(1 << S):
            if dp[i - 1][j]:
                if steps[i - 1] == '+':
                    new_power = (j + 1) % (1 << S)
                    if new_power < (1 << S):
                        dp[i][new_power] = 1
                elif steps[i - 1] == 'x':
                    new_power = (j * 2) % (1 << S)
                    if new_power < (1 << S):
                        dp[i][new_power] = 1

    # Reconstruct the optimal sequence of steps
    result = list(steps)
    current_power = 1
    for i in range(M - 1, -1, -1):
        if dp[i + 1][current_power]:
            continue
        else:
            if steps[i] == '+':
                result[i] = 'o'
            elif steps[i] == 'x':
                result[i] = 'o'
            current_power = (current_power // 2) % (1 << S)

    return ''.join(result)

